{"command": "python3 -c "
import struct
def f32(x): return struct.unpack('f', struct.pack('f', x))[0]
def shortest(x):
    # find shortest decimal string that round-trips to f32 x
    for p in range(1,10):
        for e in range(-6,8):
            c = round(x, p-e) if False else None
    # brute: try formats
    for prec in range(1,12):
        for fmt in ['%.{}f'.format(prec), '%.{}e'.format(prec)]:
            for val in [x]:
                s = fmt % val
                try:
                    if f32(float(s)) == x: return s
                except: pass
    return None
