// Svgbob: ascii art to svg converter.

pub const CELL_W: f32 = 8.0;
pub const CELL_H: f32 = 16.0;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Style {
    Solid,
    Broken,
}

#[derive(Clone, Debug)]
pub enum Elem {
    Line {
        x1: f32,
        y1: f32,
        x2: f32,
        y2: f32,
        style: Style,
        start_marker: Option<Marker>,
        end_marker: Option<Marker>,
    },
    Path {
        d: String,
        style: Style,
    },
    Circle {
        cx: f32,
        cy: f32,
        r: f32,
        style: Style,
    },
    Rect {
        x: f32,
        y: f32,
        w: f32,
        h: f32,
        style: Style,
        rx: f32,
    },
    Polygon {
        points: String,
    },
    Text {
        x: f32,
        y: f32,
        content: String,
    },
    Group(Vec<Elem>),
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Marker {
    Arrow,
    Diamond,
    Circle,
    OpenCircle,
    BigOpenCircle,
}

impl Marker {
    fn name(&self) -> &'static str {
        match self {
            Marker::Arrow => "arrow",
            Marker::Diamond => "diamond",
            Marker::Circle => "circle",
            Marker::OpenCircle => "open_circle",
            Marker::BigOpenCircle => "big_open_circle",
        }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Options {
    pub background: String,
    pub fill_color: String,
    pub stroke_color: String,
    pub font_family: String,
    pub font_size: i64,
    pub stroke_width: f64,
    pub scale: f32,
}

pub struct Spec {
    pub rows: usize,
    pub cols: usize,
    pub cells: Vec<Vec<char>>,
    pub opts: Options,
    pub elems: Vec<Elem>,
}

fn f32s(v: f32) -> String {
    let mut buf = String::new();
    // mimic rust f32 Display
    buf.push_str(&format!("{}", v));
    buf
}

fn fmt_num(v: f32) -> String {
    format!("{}", v)
}
RUSTEOF
echo written"}

