// --- run extraction --------------------------------------------------------

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Dir {
    H,
    V,
    DSlash,  // '/' going down-left
    DBack,   // '\' going down-right
}

#[derive(Clone, Debug)]
pub struct Seg {
    pub dir: Dir,
    pub cells: Vec<(usize, usize)>,
}

impl Seg {
    fn start(&self) -> (usize, usize) {
        self.cells[0]
    }
    fn end(&self) -> (usize, usize) {
        *self.cells.last().unwrap()
    }
}

fn is_marker(k: Kind) -> bool {
    matches!(k, Kind::MOpen | Kind::MBig | Kind::MDot)
}
fn is_h_arrow(k: Kind) -> bool {
    matches!(k, Kind::ArrowL | Kind::ArrowR)
}
fn is_v_arrow(k: Kind) -> bool {
    matches!(k, Kind::ArrowU | Kind::ArrowD)
}
fn is_corner(k: Kind) -> bool {
    matches!(k, Kind::CornerTop | Kind::CornerBot | Kind::CornerApos)
}
fn is_paren(k: Kind) -> bool {
    matches!(k, Kind::ParenL | Kind::ParenR)
}
fn is_diag(k: Kind) -> bool {
    matches!(k, Kind::Slash | Kind::Back)
