// ---------------------------------------------------------------------------
// Geometry helpers

const CW: f32 = 8.0; // cell width
const CH: f32 = 16.0; // cell height
const HW: f32 = 4.0; // half cell width
const HH: f32 = 8.0; // half cell height

fn cell_cx(c: usize) -> f32 {
    c as f32 * CW + HW
}
fn cell_cy(r: usize) -> f32 {
    r as f32 * CH + HH
}
fn cell_left(c: usize) -> f32 {
    c as f32 * CW
}
fn cell_right(c: usize) -> f32 {
    (c + 1) as f32 * CW
}
fn cell_top(r: usize) -> f32 {
    r as f32 * CH
}
fn cell_bot(r: usize) -> f32 {
    (r + 1) as f32 * CH
}

// ---------------------------------------------------------------------------
// Rect detection

pub struct RectShape {
    pub r0: usize,
    pub c0: usize,
    pub r1: usize,
    pub c1: usize,
    pub rx: f32,
    pub broken: bool,
}

fn corner_ok_for(g: &Grid, r: usize, c: usize, which: u8) -> bool {
    // which: 0=TL 1=TR 2=BL 3=BR
    let k = g.at(r as isize, c as isize);
    match which {
        0 | 1 => k == Kind::Plus || k == Kind::CornerTop,
        2 => k == Kind::Plus || k == Kind::CornerBot || k == Kind::CornerApos,
        3 => k == Kind::Plus || k == Kind::CornerApos,
        _ => false,
    }
}

fn count_conns(g: &Grid, r: usize, c: usize) -> usize {
    let mut n = 0;
    for (dr, dc) in [(0isize, -1isize), (0, 1), (-1, 0), (1, 0)] {
        let nr = r as isize + dr;
        let nc = c as isize + dc;
        let a = g.at(nr, nc);
        let b = g.at(r as isize, c as isize);
        let conn = if dr == 0 {
            if dc < 0 {
                h_conn(a, b)
            } else {
                h_conn(b, a)
            }
        } else if dr < 0 {
            v_conn(a, b)
        } else {
            v_conn(b, a)
        };
        if conn {
            n += 1;
        }
    }
    n
}

fn edge_cells_ok(g: &Grid, r: usize, c0: usize, c1: usize) -> bool {
    // horizontal edge between c0 and c1 exclusive
    for c in c0 + 1..c1 {
        let k = g.at(r as isize, c as isize);
        if k != Kind::H && k != Kind::Tilde {
            return false;
        }
    }
    true
}
fn vedge_cells_ok(g: &Grid, c: usize, r0: usize, r1: usize) -> bool {
    for r in r0 + 1..r1 {
        let k = g.at(r as isize, c as isize);
        if k != Kind::V {
            return false;
        }
    }
    true
}
