fn find_rects(g: &Grid, used: &mut Vec<Vec<bool>>) -> Vec<RectShape> {
    let mut rects = Vec::new();
    for r in 0..g.rows {
        for c in 0..g.cols {
            if used[r][c] {
                continue;
            }
            if !corner_ok_for(g, r, c, 0) {
                continue;
            }
            if !tl_valid(g, r, c) {
                continue;
            }
            // scan right for TR corner
            let mut c2 = c + 1;
            while c2 < g.cols {
                if !h_connected_cells(g, r, c2 - 1, r, c2) {
                    break;
                }
                if corner_ok_for(g, r, c2, 1) && tr_valid(g, r, c2) {
                    // found TR candidate at c2
                    // scan down for BR corner
                    let mut r2 = r + 1;
                    let mut found = false;
                    while r2 < g.rows {
                        if !v_connected_cells(g, r2 - 1, c2, r2, c2) {
                            break;
                        }
                        if corner_ok_for(g, r2, c2, 3) && br_valid(g, r2, c2) {
                            // scan left for BL corner
                            let mut c3 = c2;
                            let mut bl = None;
                            while c3 > c {
                                if !h_connected_cells(g, r2, c3 - 1, r2, c3) {
                                    break;
                                }
                                if c3 - 1 == c {
                                    if corner_ok_for(g, r2, c, 2) && bl_valid(g, r2, c) {
                                        bl = Some(c);
                                    }
                                    break;
                                }
                                c3 -= 1;
                            }
                            if let Some(c3) = bl {
                                if vedge_cells_ok(g, c, r, r2)
                                    && vedge_cells_ok(g, c2, r, r2)
                                    && edge_cells_ok(g, r, c, c2)
                                    && edge_cells_ok(g, r2, c, c2)
                                {
                                    let mut broken = false;
                                    for cc in c + 1..c2 {
                                        if g.at(r as isize, cc as isize) == Kind::Tilde
                                            || g.at(r2 as isize, cc as isize) == Kind::Tilde
                                        {
                                            broken = true;
                                        }
                                    }
                                    for rr in r + 1..r2 {
                                        if g.at(rr as isize, c as isize) == Kind::Tilde
                                            || g.at(rr as isize, c2 as isize) == Kind::Tilde
                                        {
                                            broken = true;
                                        }
                                    }
                                    let mut rx = 0.0;
                                    for &(rr, cc, w) in [
                                        (r, c, 0u8),
                                        (r, c2, 1),
                                        (r2, c2, 3),
                                        (r2, c, 2),
                                    ]
                                    .iter()
                                    {
                                        let k = g.at(rr as isize, cc as isize);
                                        if matches!(
                                            k,
                                            Kind::CornerTop | Kind::CornerBot | Kind::CornerApos
                                        ) {
                                            rx = HW;
                                        }
                                        let _ = w;
                                        used[rr][cc] = true;
                                    }
                                    for rr in r..=r2 {
                                        used[rr][c] = true;
                                        used[rr][c2] = true;
                                    }
                                    for cc in c..=c2 {
                                        used[r][cc] = true;
                                        used[r2][cc] = true;
                                    }
                                    rects.push(RectShape {
                                        r0: r,
                                        c0: c,
                                        r1: r2,
                                        c1: c2,
                                        rx,
                                        broken,
                                    });
                                    found = true;
                                    break;
                                }
                            }
                        }
                        r2 += 1;
                    }
                    if found {
                        break;
                    }
                }
                c2 += 1;
            }
        }
    }
    rects
}

fn h_connected_cells(g: &Grid, r1: usize, c1: usize, r2: usize, c2: usize) -> bool {
