#[derive(Clone, Debug)]
pub enum Item {
    Pieces(Vec<Piece>),
    Other(Elem),
    Group(Vec<Elem>),
}

// markers map
fn marker_of(k: Kind) -> Option<Marker> {
    match k {
        Kind::MOpen => Some(Marker::OpenCircle),
        Kind::MBig => Some(Marker::BigOpenCircle),
        Kind::MDot => Some(Marker::Circle),
        _ => None,
    }
}

pub struct Trace {
    pub items: Vec<Item>,
}

fn piece_marker(kind: Kind, at_start: bool) -> Option<Marker> {
    marker_of(kind).filter(|_| at_start)
}

// compute pieces for a run, appending extra elements
pub fn run_pieces(g: &Grid, seg: &Seg) -> (Vec<Piece>, Vec<Elem>) {
    let mut pieces: Vec<Piece> = Vec::new();
    let mut extras: Vec<Elem> = Vec::new();
    match seg.dir {
        Dir::H => {
            let r = seg.cells[0].0;
            let y = cell_cy(r);
            // break points
            let mut chunks: Vec<(usize, usize)> = Vec::new(); // inclusive cell ranges
            let mut start = 0usize;
            for i in 0..seg.cells.len() {
                let c = seg.cells[i].1;
                let k = g.at(r as isize, c as isize);
                if breaks(k) {
                    if i > start {
                        chunks.push((start, i - 1));
                    }
                    start = i + 1;
                }
            }
            if start < seg.cells.len() {
                chunks.push((start, seg.cells.len() - 1));
            }
            // build pieces per chunk
            let mut idx = 0usize;
            for (a, b) in &chunks {
                let ca = seg.cells[*a].1;
                let cb = seg.cells[*b].1;
                let ka = g.at(r as isize, ca as isize);
                let kb = g.at(r as isize, cb as isize);
                // offsets
                let mut x1 = cell_left(ca);
                let mut x2 = cell_right(cb);
                match ka {
                    Kind::MOpen | Kind::MBig | Kind::MDot => x1 = cell_cx(ca),
                    Kind::ArrowL | Kind::ArrowR | Kind::CornerTop | Kind::CornerBot
                    | Kind::CornerApos | Kind::ArrowU | Kind::ArrowD => x1 = cell_right(ca),
                    Kind::Plus | Kind::V | Kind::Slash | Kind::Back => x1 = cell_cx(ca),
                    _ => {}
                }
                match kb {
                    Kind::MOpen | Kind::MBig | Kind::MDot => x2 = cell_cx(cb),
                    Kind::ArrowL | Kind::ArrowR | Kind::CornerTop | Kind::CornerBot
                    | Kind::CornerApos | Kind::ArrowU | Kind::ArrowD => x2 = cell_left(cb),
                    Kind::Plus | Kind::V | Kind::Slash | Kind::Back => x2 = cell_cx(cb),
                    _ => {}
                }
                // style: broken if any cell is a tilde
                let mut broken = false;
                for i in *a..=*b {
                    if g.at(r as isize, seg.cells[i].1 as isize) == Kind::Tilde {
                        broken = true;
                    }
                }
                // markers: end marker if the chunk's last cell is a marker
                let mut sm: Option<Marker> = None;
                let mut em: Option<Marker> = None;
                if let Some(m) = marker_of(kb) {
                    em = Some(m);
                }
                // start marker handled via stub (chunk starting with marker cell)
                // but chunk never starts with marker because breaks() split it.
                // However marker could be first cell of run: then a chunk before it doesn't exist;
                // stub is created separately.
                let st = *a == 0 && matches!(ka, Kind::MOpen | Kind::MBig | Kind::MDot);
                if st {
                    // stub line from center to center+12
                    let cx = cell_cx(ca);
                    let m = marker_of(ka).unwrap();
                    pieces.push(Piece {
                        x1: cx + 12.0,
                        y1: y,
                        x2: cx,
                        y2: y,
                        style: Style::Solid,
                        start_marker: None,
                        end_marker: Some(m),
                    });
                    x1 = cx + 12.0;
                    idx += 1;
                }
                let _ = idx;
                if x2 - x1 > 0.01 {
                    pieces.push(Piece {
                        x1,
                        y1: y,
                        x2,
                        y2: y,
                        style: if broken { Style::Broken } else { Style::Solid },
                        start_marker: sm,
                        end_marker: em,
                    });
                } else if em.is_some() {
                    // zero-length main line but marker present (arrow/marker)
                }
                // arrow polygon / chevron
                for i in *a..=*b {
                    let c = seg.cells[i].1;
                    let k = g.at(r as isize, c as isize);
                    if is_h_arrow(k) {
                        let cx = cell_cx(c);
                        let cy = y;
                        let left = cell_left(c);
                        let right = cell_right(c);
                        // direction the arrow points
                        let points_right = k == Kind::ArrowR;
                        // determine if the arrow points away from the connector
                        let has_left_conn = i > 0
                            && h_conn(
                                g.at(r as isize, (c - 1) as isize),
                                g.at(r as isize, c as isize),
                            );
                        let has_right_conn = i + 1 < seg.cells.len()
                            && h_conn(
                                g.at(r as isize, c as isize),
                                g.at(r as isize, (c + 1) as isize),
                            );
                        let is_start = i == 0;
                        let is_end = i == seg.cells.len() - 1;
                        let points_away = if is_start && is_end {
                            true
                        } else if is_start {
                            points_right != has_right_conn
                        } else if is_end {
                            points_right == has_left_conn
                        } else {
                            // middle: points away from the side it came from
                            !has_left_conn && has_right_conn || has_left_conn && !has_right_conn
                        };
                        let _ = points_away;
                        // polygon when pointing away, chevron when pointing into connector
                        let away = if is_start && is_end {
                            !has_left_conn && !has_right_conn
                        } else if is_start {
                            points_right != has_right_conn
                        } else if is_end {
                            points_right == has_left_conn
                        } else {
                            true
                        };
                        if away {
                            let tip = if points_right { right } else { left };
                            let base = if points_right { left } else { right };
                            extras.push(Elem::Polygon {
                                points: format!(
                                    "{},{} {},{} {},{}",
                                    fmt(base),
                                    fmt(cy - HW),
                                    fmt(tip),
                                    fmt(cy),
                                    fmt(base),
                                    fmt(cy + HW)
                                ),
                            });
                        } else {
                            let tip = if points_right { right } else { left };
                            let base = if points_right { left } else { right };
                            extras.push(Elem::Path {
                                d: format!(
                                    "M {},{} L {},{} L {},{}",
                                    fmt(base),
                                    fmt(cy - HW),
                                    fmt(tip),
                                    fmt(cy),
                                    fmt(base),
                                    fmt(cy + HW)
                                ),
                                style: Style::Solid,
                            });
                        }
                    }
                }
            }
        }
        _ => {}
    }
    (pieces, extras)
}

pub fn fmt(v: f32) -> String {
    format!("{}", v)
}
RUSTEOF
echo ok"}

