                            && h_conn(
                                g.at(r as isize, (c - 1) as isize),
                                g.at(r as isize, c as isize),
                            );
                        let has_right_conn = i + 1 < seg.cells.len()
                            && h_conn(
                                g.at(r as isize, c as isize),
                                g.at(r as isize, (c + 1) as isize),
                            );
                        let is_start = i == 0;
                        let is_end = i == seg.cells.len() - 1;
                        let points_away = if is_start && is_end {
                            true
                        } else if is_start {
                            points_right != has_right_conn
                        } else if is_end {
                            points_right == has_left_conn
                        } else {
                            // middle: points away from the side it came from
                            !has_left_conn && has_right_conn || has_left_conn && !has_right_conn
                        };
                        let _ = points_away;
                        // polygon when pointing away, chevron when pointing into connector
                        let away = if is_start && is_end {
                            !has_left_conn && !has_right_conn
                        } else if is_start {
                            points_right != has_right_conn
                        } else if is_end {
                            points_right == has_left_conn
                        } else {
                            true
                        };
                        if away {
                            let tip = if points_right { right } else { left };
                            let base = if points_right { left } else { right };
                            extras.push(Elem::Polygon {
                                points: format!(
                                    "{},{} {},{} {},{}",
                                    fmt(base),
                                    fmt(cy - HW),
                                    fmt(tip),
                                    fmt(cy),
                                    fmt(base),
                                    fmt(cy + HW)
                                ),
                            });
                        } else {
                            let tip = if points_right { right } else { left };
                            let base = if points_right { left } else { right };
                            extras.push(Elem::Path {
                                d: format!(
                                    "M {},{} L {},{} L {},{}",
                                    fmt(base),
                                    fmt(cy - HW),
                                    fmt(tip),
                                    fmt(cy),
                                    fmt(base),
                                    fmt(cy + HW)
                                ),
                                style: Style::Solid,
                            });
                        }
                    }
                }
            }
        }
        _ => {}
    }
    (pieces, extras)
}

pub fn fmt(v: f32) -> String {
    format!("{}", v)
}
