// ---------------------------------------------------------------------------
// pieces

#[derive(Clone, Debug)]
pub struct Piece {
    pub x1: f32,
    pub y1: f32,
    pub x2: f32,
    pub y2: f32,
    pub style: Style,
    pub start_marker: Option<Marker>,
    pub end_marker: Option<Marker>,
}

impl Piece {
    fn to_out(&self) -> Out {
        Out::Line {
            x1: self.x1,
            y1: self.y1,
            x2: self.x2,
            y2: self.y2,
            style: self.style,
            start_marker: self.start_marker,
            end_marker: self.end_marker,
        }
    }
    fn length(&self) -> f32 {
        ((self.x2 - self.x1) * (self.x2 - self.x1) + (self.y2 - self.y1) * (self.y2 - self.y1))
            .sqrt()
    }
    fn contains(&self, x: f32, y: f32) -> bool {
        let eps = 0.6;
        let minx = self.x1.min(self.x2) - eps;
        let maxx = self.x1.max(self.x2) + eps;
        let miny = self.y1.min(self.y2) - eps;
        let maxy = self.y1.max(self.y2) + eps;
        x >= minx && x <= maxx && y >= miny && y <= maxy
    }
    fn touches_end(&self, x: f32, y: f32) -> bool {
        // is (x,y) near either endpoint of the piece
        let d1 = (self.x1 - x) * (self.x1 - x) + (self.y1 - y) * (self.y1 - y);
        let d2 = (self.x2 - x) * (self.x2 - x) + (self.y2 - y) * (self.y2 - y);
        d1 < 0.25 || d2 < 0.25
    }
}

// vertical connection of a corner cell: returns (row of pipe, aligned)
fn corner_vconn(g: &Grid, r: usize, c: usize, down: bool) -> Option<(isize, bool)> {
    // down=true means the corner connects downward ('.'), else upward ('`'/'\'')
    let s: isize = if down { 1 } else { -1 };
    let rr = r as isize + s;
    // aligned
    if g.k(rr, c as isize) == Kind::V && v_conn(g.k(rr, c as isize), g.k(r as isize, c as isize)) {
        return Some((rr, true));
    }
    // diagonal: opposite side from the horizontal connection is handled by caller.
    // We check both diagonals here; caller validates.
    for dc in [-1isize, 1isize] {
        let cc = c as isize + dc;
        if g.k(rr, cc) == Kind::V && v_conn(g.k(rr, cc), g.k(r as isize, c as isize)) {
            return Some((cc, false));
        }
    }
    None
}

// horizontal direction sign of a corner's horizontal connection: +1 if dash to right
fn corner_hdir(g: &Grid, r: usize, c: usize) -> i32 {
    let left_conn = c > 0 && h_conn(g.krc(r, c - 1), g.krc(r, c));
    let right_conn = c + 1 < g.cols && h_conn(g.krc(r, c), g.krc(r, c + 1));
    if left_conn {
        -1
    } else if right_conn {
        1
    } else {
        0
    }
}

// produces the corner arc element plus the adjusted endpoints
struct CornerArc {
    x1: f32,
    y1: f32,
    x2: f32,
    y2: f32,
    radius: f32,
    sweep: i32,
    h_end: (f32, f32),  // endpoint on the horizontal line
    v_end: (f32, f32),  // endpoint on the vertical line
}

fn corner_arc(g: &Grid, r: usize, c: usize, hdir: i32) -> Option<CornerArc> {
    let k = g.krc(r, c);
    let down = k == Kind::CornerTop;
    let vd: f32 = if down { 1.0 } else { -1.0 };
    let vc = corner_vconn(g, r, c, down)?;
    let (vr, aligned) = vc;
    let vx = cx(vr as usize);
    let vy = cy(r);
    let hd = hdir as f32;
    let radius = if aligned { HW } else { HH };
    let acx = vx + hd * radius;
    let acy = vy + vd * radius;
    let h_end = (vx + hd * radius, vy);
    let v_end = (vx, vy + vd * radius);
    let sweep: i32 = if hdir > 0 { 0 } else { 1 };
    let (p1, p2) = if down {
        (h_end, v_end)
    } else {
        (v_end, h_end)
    };
    Some(CornerArc {
        x1: p1.0,
        y1: p1.1,
        x2: p2.0,
        y2: p2.1,
        radius,
        sweep,
        h_end,
        v_end,
    })
}

fn corner_out(arc: &CornerArc) -> Out {
    Out::Path {
        d: format!(
            "M {},{} A {},{} 0,0,{} {},{}",
            fmt(arc.x1),
            fmt(arc.y1),
            fmt(arc.radius),
            fmt(arc.radius),
            arc.sweep,
            fmt(arc.x2),
            fmt(arc.y2)
        ),
        style: Style::Solid,
    }
}
RUSTEOF
echo ok"}

