    x1: f32,
    y1: f32,
    x2: f32,
    y2: f32,
    radius: f32,
    sweep: i32,
    h_end: (f32, f32),  // endpoint on the horizontal line
    v_end: (f32, f32),  // endpoint on the vertical line
}

fn corner_arc(g: &Grid, r: usize, c: usize, hdir: i32) -> Option<CornerArc> {
    let k = g.krc(r, c);
    let down = k == Kind::CornerTop;
    let vd: f32 = if down { 1.0 } else { -1.0 };
    let vc = corner_vconn(g, r, c, down)?;
    let (vr, aligned) = vc;
    let vx = cx(vr as usize);
    let vy = cy(r);
    let hd = hdir as f32;
    let radius = if aligned { HW } else { HH };
    let acx = vx + hd * radius;
    let acy = vy + vd * radius;
    let h_end = (vx + hd * radius, vy);
    let v_end = (vx, vy + vd * radius);
    let sweep: i32 = if hdir > 0 { 0 } else { 1 };
    let (p1, p2) = if down {
        (h_end, v_end)
    } else {
        (v_end, h_end)
    };
    Some(CornerArc {
        x1: p1.0,
        y1: p1.1,
        x2: p2.0,
        y2: p2.1,
        radius,
        sweep,
        h_end,
        v_end,
    })
}

fn corner_out(arc: &CornerArc) -> Out {
    Out::Path {
        d: format!(
            "M {},{} A {},{} 0,0,{} {},{}",
            fmt(arc.x1),
            fmt(arc.y1),
            fmt(arc.radius),
            fmt(arc.radius),
            arc.sweep,
            fmt(arc.x2),
            fmt(arc.y2)
        ),
        style: Style::Solid,
    }
}
