// compute pieces/extras for a run
pub fn run_out(g: &Grid, seg: &Seg) -> (Vec<Piece>, Vec<Out>) {
    let mut pieces: Vec<Piece> = Vec::new();
    let mut extras: Vec<Out> = Vec::new();
    match seg.dir {
        Dir::H => {
            let r = seg.cells[0].0;
            let y = cy(r);
            let n = seg.cells.len();
            let bidx: Vec<usize> = (0..n)
                .filter(|&i| breaks(g.krc(r, seg.cells[i].1)))
                .collect();
            let mut chunks: Vec<(usize, usize)> = Vec::new();
            let mut s = 0usize;
            for &i in &bidx {
                if i > s {
                    chunks.push((s, i - 1));
                }
                s = i + 1;
            }
            if s < n {
                chunks.push((s, n - 1));
            }
            if chunks.is_empty() {
                // entire run is break cells
            }
            for &(a, b) in &chunks {
                let ca = seg.cells[a].1;
                let cb = seg.cells[b].1;
                let ka = g.krc(r, ca);
                let kb = g.krc(r, cb);
                let mut broken = false;
                for i in a..=b {
                    if g.krc(r, seg.cells[i].1) == Kind::Tilde {
                        broken = true;
                    }
                }
                let mut x1 = left(ca);
                let mut x2 = right(cb);
                // start
                if a == 0 {
                    match ka {
                        Kind::MOpen | Kind::MBig | Kind::MDot => x1 = cx(ca),
                        Kind::ArrowL | Kind::ArrowR => x1 = right(ca),
                        Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                            if let Some(arc) = corner_arc(g, r, ca, 1) {
                                x1 = arc.h_end.0;
                            }
                        }
                        Kind::ArrowU | Kind::ArrowD => x1 = right(ca),
                        Kind::Plus | Kind::V | Kind::Slash | Kind::Back => x1 = cx(ca),
                        Kind::ParenL => x1 = right(ca),
                        Kind::ParenR => x1 = left(ca),
                        _ => {}
                    }
                } else {
                    // preceded by break cell
                    let pk = g.krc(r, seg.cells[a - 1].1);
                    x1 = match pk {
                        Kind::MOpen => cx(seg.cells[a - 1].1) + HW,
                        Kind::MBig => cx(seg.cells[a - 1].1) + HW,
                        Kind::MDot => cx(seg.cells[a - 1].1) - HW,
                        Kind::ArrowL | Kind::ArrowR | Kind::ArrowU | Kind::ArrowD
                        | Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                            right(seg.cells[a - 1].1)
                        }
                        _ => right(seg.cells[a - 1].1),
                    };
                }
                // end
                if b == n - 1 {
                    match kb {
                        Kind::MOpen | Kind::MBig | Kind::MDot => x2 = cx(cb),
                        Kind::ArrowL | Kind::ArrowR => x2 = left(cb),
                        Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                            if let Some(arc) = corner_arc(g, r, cb, -1) {
                                x2 = arc.h_end.0;
                            }
                        }
                        Kind::ArrowU | Kind::ArrowD => x2 = left(cb),
                        Kind::Plus | Kind::V | Kind::Slash | Kind::Back => x2 = cx(cb),
                        Kind::ParenL => x2 = right(cb),
                        Kind::ParenR => x2 = left(cb),
                        _ => {}
                    }
                } else {
                    let nk = g.krc(r, seg.cells[b + 1].1);
                    x2 = match nk {
                        Kind::MOpen | Kind::MBig | Kind::MDot => cx(seg.cells[b + 1].1),
                        Kind::ArrowL | Kind::ArrowR | Kind::ArrowU | Kind::ArrowD
                        | Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                            left(seg.cells[b + 1].1)
                        }
                        _ => left(seg.cells[b + 1].1),
                    };
                }
                // markers
                let mut em: Option<Marker> = None;
                if b == n - 1 {
                    if let Some(m) = marker_of(kb) {
                        em = Some(m);
                    }
                }
                let mut sm: Option<Marker> = None;
                if a > 0 {
                    let pk = g.krc(r, seg.cells[a - 1].1);
                    if let Some(m) = marker_of(pk) {
                        sm = Some(m);
                    }
                }
                if x2 > x1 + 0.01 {
                    pieces.push(Piece {
                        x1,
                        y1: y,
                        x2,
                        y2: y,
                        style: if broken { Style::Broken } else { Style::Solid },
                        start_marker: sm,
                        end_marker: em,
                    });
                }
            }
            // stub for marker at run start
            let k0 = g.krc(r, seg.cells[0].1);
            if let Some(m) = marker_of(k0) {
                let c0 = seg.cells[0].1;
                let ccx = cx(c0);
                // stub from center to center + 12 (pointing right)
                pieces.insert(
                    0,
                    Piece {
                        x1: ccx + 12.0,
                        y1: y,
                        x2: ccx,
                        y2: y,
                        style: Style::Solid,
                        start_marker: None,
                        end_marker: Some(m),
                    },
                );
            }
            // break-cell elements in order
            for &i in &bidx {
                let c = seg.cells[i].1;
                let k = g.krc(r, c);
                if let Some(m) = marker_of(k) {
                    if i == 0 {
                        continue; // stub already added
                    }
                    // stub when the marker starts a segment going right and nothing to the left
                    let has_left = i > 0
                        && h_conn(g.krc(r, seg.cells[i - 1].1), g.krc(r, seg.cells[i].1));
                    let has_right = i + 1 < n
                        && h_conn(g.krc(r, seg.cells[i].1), g.krc(r, seg.cells[i + 1].1));
                    let ccx = cx(c);
                    if has_right && !has_left {
                        extras.push(Out::Line {
                            x1: ccx + 12.0,
                            y1: y,
                            x2: ccx,
                            y2: y,
                            style: Style::Solid,
                            start_marker: None,
                            end_marker: Some(m),
                        });
                    }
                    continue;
                }
                if is_h_arrow(k) {
                    let left_c = left(c);
                    let right_c = right(c);
                    let points_right = k == Kind::ArrowR;
                    let has_left = i > 0
                        && h_conn(g.krc(r, seg.cells[i - 1].1), g.krc(r, seg.cells[i].1));
                    let has_right = i + 1 < n
                        && h_conn(g.krc(r, seg.cells[i].1), g.krc(r, seg.cells[i + 1].1));
                    let is_start = i == 0;
                    let is_end = i == n - 1;
                    let away = if is_start && is_end {
                        false
                    } else if is_start {
                        points_right == has_right
                    } else if is_end {
                        points_right != has_left
                    } else {
                        true
                    };
                    let tip = if points_right { right_c } else { left_c };
                    let base = if points_right { left_c } else { right_c };
                    if away {
                        extras.push(Out::Poly {
                            points: format!(
                                "{},{}, {},{}, {},{}",
                                fmt(base),
                                fmt(y - HW),
                                fmt(tip),
                                fmt(y),
                                fmt(base),
                                fmt(y + HW)
                            ),
                        });
                    } else {
                        extras.push(Out::Path {
                            d: format!(
                                "M {},{} L {},{} L {},{}",
                                fmt(base),
                                fmt(y - HW),
                                fmt(tip),
                                fmt(y),
                                fmt(base),
                                fmt(y + HW)
                            ),
                            style: Style::Solid,
                        });
                    }
                    continue;
                }
                if is_corner(k) {
                    // horizontal direction: dash to the right?
                    let hd = if i + 1 < n && h_conn(g.krc(r, seg.cells[i].1), g.krc(r, seg.cells[i + 1].1)) {
                        1
                    } else if i > 0 && h_conn(g.krc(r, seg.cells[i - 1].1), g.krc(r, seg.cells[i].1)) {
                        -1
                    } else {
                        0
                    };
                    if hd != 0 {
                        if let Some(arc) = corner_arc(g, r, c, hd) {
                            extras.push(corner_out(&arc));
                        }
                    }
                    continue;
                }
            }
        }
        _ => {}
    }
    (pieces, extras)
}
RUSTEOF
echo ok"}

