            let mut s = 0usize;
            for &i in &bidx {
                if i > s {
                    chunks.push((s, i - 1));
                }
                s = i + 1;
            }
            if s < n {
                chunks.push((s, n - 1));
            }
            if chunks.is_empty() {
                // entire run is break cells
            }
            for &(a, b) in &chunks {
                let ca = seg.cells[a].1;
                let cb = seg.cells[b].1;
