                if a == 0 {
                    match ka {
                        Kind::MOpen | Kind::MBig | Kind::MDot => x1 = cx(ca),
                        Kind::ArrowL | Kind::ArrowR => x1 = right(ca),
                        Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                            if let Some(arc) = corner_arc(g, r, ca, 1) {
