            style: if rect.broken { Style::Broken } else { Style::Solid },
            rx: rect.rx,
        });
    }
    // ---- circles ----
    find_circles(g, &mut used, &mut out);

    // ---- '#' blocks and '=' double lines ----
    for r in 0..g.rows {
        for c in 0..g.cols {
            if used[r][c] {
                continue;
            }
            let k = g.krc(r, c);
            if k == Kind::Block {
                out.push(Out::Rect {
                    x: cx(c) - HW,
                    y: cy(r) - HW,
                    w: CW,
                    h: CW,
                    style: Style::Solid,
                    rx: 0.0,
                });
                used[r][c] = true;
            } else if k == Kind::Double {
                out.push(Out::Line {
                    x1: left(c),
                    y1: cy(r) - 2.0,
                    x2: right(c),
                    y2: cy(r) - 2.0,
                    style: Style::Solid,
                    start_marker: None,
                    end_marker: None,
                });
                out.push(Out::Line {
                    x1: left(c),
                    y1: cy(r) + 2.0,
                    x2: right(c),
                    y2: cy(r) + 2.0,
                    style: Style::Solid,
                    start_marker: None,
                    end_marker: None,
                });
                used[r][c] = true;
            }
        }
    }

    // ---- runs ----
    let runs = collect_runs(g, &used);
    for seg in &runs {
        let (pieces, extras) = run_out(g, seg);
        // filter zero length pieces
        let pieces: Vec<Piece> = pieces
            .into_iter()
            .filter(|p| p.length() > 0.01)
            .collect();
        if pieces.is_empty() {
            for e in extras {
                out.push(e);
            }
            continue;
        }
        emit_pieces(&mut out, pieces, extras, g);
    }

    // ---- text ----
    emit_text(g, &used, &mut out);

    out
}

// merge pieces with existing output
fn emit_pieces(out: &mut Vec<Out>, pieces: Vec<Piece>, extras: Vec<Out>, _g: &Grid) {
    // find merging target
    let mut merged_into: Option<usize> = None;
    for (i, o) in out.iter().enumerate() {
        let lines: Vec<&Piece> = match o {
            Out::Line {
                ..
            } => vec![], // handled separately
            Out::Group(v) => v
                .iter()
                .filter_map(|e| match e {
                    Out::Line {
                        ..
                    } => None,
                    _ => None,
                })
                .collect(),
            _ => vec![],
        };
        let _ = lines;
        let _ = i;
    }
    let _ = merged_into;
    // simpler approach: build list of line descriptors from output items
    // (we keep it straightforward: check each piece's endpoints against all lines)
    let mut new_pieces = pieces;
    let mut merged: Option<usize> = None;
    for (idx, p) in new_pieces.iter().enumerate() {
        // check endpoints against existing lines in out
        let mut target: Option<usize> = None;
        for (oi, o) in out.iter().enumerate() {
            match o {
                Out::Line {
                    x1,
                    y1,
                    x2,
                    y2,
                    ..
                } => {
                    let pl = Piece {
                        x1: *x1,
                        y1: *y1,
                        x2: *x2,
                        y2: *y2,
                        style: Style::Solid,
                        start_marker: None,
                        end_marker: None,
                    };
                    if pl.contains(p.x1, p.y1) || pl.contains(p.x2, p.y2) {
                        target = Some(oi);
                        break;
                    }
                }
                Out::Group(v) => {
                    for e in v {
                        if let Out::Line {
                            x1,
                            y1,
                            x2,
                            y2,
                            ..
                        } = e
                        {
                            let pl = Piece {
                                x1: *x1,
                                y1: *y1,
                                x2: *x2,
                                y2: *y2,
                                style: Style::Solid,
                                start_marker: None,
                                end_marker: None,
                            };
                            if pl.contains(p.x1, p.y1) || pl.contains(p.x2, p.y2) {
                                target = Some(oi);
                                break;
                            }
                        }
                    }
                    if target.is_some() {
                        break;
                    }
                }
                _ => {}
            }
        }
        if let Some(oi) = target {
            // merge into existing group or create one
            match out[oi].clone() {
                Out::Line {
                    x1,
                    y1,
                    x2,
                    y2,
                    style,
                    start_marker,
                    end_marker,
                } => {
                    let existing = Out::Line {
                        x1,
                        y1,
                        x2,
                        y2,
                        style,
                        start_marker,
                        end_marker,
                    };
                    let mut v = vec![existing];
                    for q in new_pieces.drain(0..) {
                        v.push(q.to_out());
                    }
                    out[oi] = Out::Group(v);
                }
                Out::Group(mut v) => {
                    for q in new_pieces.drain(0..) {
                        v.push(q.to_out());
                    }
                    out[oi] = Out::Group(v);
                }
                _ => {}
            }
            merged = Some(oi);
            break;
        }
    }
    let remaining = new_pieces;
    if merged.is_some() {
        // extras appended after group
        for e in extras {
            out.push(e);
        }
    } else {
        for p in remaining {
            out.push(p.to_out());
        }
        for e in extras {
            out.push(e);
        }
    }
}
RUSTEOF
echo ok"}

