            match kb {
                Kind::MOpen | Kind::MBig | Kind::MDot => y2 = cy(rb),
                Kind::ArrowU | Kind::ArrowD => y2 = top(rb),
                Kind::ParenL | Kind::ParenR => y2 = top(rb),
                Kind::Plus => y2 = cy(rb),
                Kind::Slash | Kind::Back => y2 = cy(rb),
                Kind::Block => y2 = cy(rb) - HW,
