                    if let Some(arc) = corner_arc(g, rb, c, hdir) {
                        y2 = arc.v_end.1;
                    }
                }
                _ => {}
            }
        } else {
            let nk = g.krc(seg.cells[b + 1].0, c);
            y2 = match nk {
                Kind::MOpen | Kind::MBig | Kind::MDot => cy(seg.cells[b + 1].0),
                Kind::ArrowU | Kind::ArrowD | Kind::ParenL | Kind::ParenR => {
                    top(seg.cells[b + 1].0)
