        let mut em: Option<Marker> = None;
        if b == n - 1 {
            if let Some(m) = marker_of(kb) {
                em = Some(m);
            }
        }
        let mut sm: Option<Marker> = None;
        if a > 0 {
            if let Some(m) = marker_of(g.krc(seg.cells[a - 1].0, c)) {
                sm = Some(m);
            }
        }
        let mut broken = false;
        for i in a..=b {
            if g.krc(seg.cells[i].0, c) == Kind::Tilde {
                broken = true;
            }
        }
        if y2 > y1 + 0.01 {
            pieces.push(Piece {
                x1: x,
                y1,
                x2: x,
