            let sweep = if k == Kind::ParenL { 0 } else { 1 };
            extras.push(Out::Path {
                d: format!(
                    "M {},{} A 12,12 0,0,{} {},{}",
                    fmt(x),
                    fmt(top(r)),
                    sweep,
                    fmt(x),
                    fmt(bot(r))
                ),
                style: Style::Solid,
            });
            continue;
        }
        if is_v_arrow(k) {
            let points_down = k == Kind::ArrowD;
            let has_up = i > 0 && v_conn(g.krc(seg.cells[i - 1].0, c), g.krc(r, c));
            let has_down = i + 1 < n && v_conn(g.krc(r, c), g.krc(seg.cells[i + 1].0, c));
            let is_start = i == 0;
            let is_end = i == n - 1;
            let away = if is_start {
                points_down == has_down
            } else if is_end {
                points_down != has_up
            } else {
                true
            };
            let tip_y = if points_down { bot(r) } else { top(r) };
            if away {
                let base_y = if points_down { bot(r) - 12.0 } else { top(r) + 12.0 };
                extras.push(Out::Poly {
