        let k = g.krc(rr, cc as usize);
        if is_corner(k) {
            // corner connects downward
            if k == Kind::CornerTop {
                let hdir = corner_hdir(g, rr, cc as usize);
                let hdirsign = hdir;
                // the corner's vertical connection: aligned or diagonal
                let diag_col = cc as isize - hdirsign as isize;
                if diag_col == c as isize {
                    return Some((rr, cc as usize));
                }
            }
        }
    }
    None
}
fn corner_below(g: &Grid, r: usize, c: usize) -> Option<(usize, usize)> {
    if r + 1 >= g.rows {
        return None;
    }
    let rr = r + 1;
    for cc in [c as isize - 1, c as isize, c as isize + 1] {
        if cc < 0 || cc as usize >= g.cols {
            continue;
        }
        let k = g.krc(rr, cc as usize);
        if is_corner(k) && k != Kind::CornerTop {
            let hdir = corner_hdir(g, rr, cc as usize);
            let diag_col = cc as isize - hdir as isize;
            if diag_col == c as isize {
                return Some((rr, cc as usize));
            }
        }
    }
    None
}
