            // bottom row: r+2
            let r2 = r + 2;
            if r2 >= g.rows {
                continue;
            }
            // check the bottom row: cells c+1..c2-1 must be dashes and the corners must be
            // bottom corners
            let bl_ok = g.krc(r2, c) == Kind::CornerBot || g.krc(r2, c) == Kind::CornerApos;
