            // geometry
            let lx = cx(c);
            let rx2 = cx(c2);
            let ty = cy(r);
            let by = cy(r2);
            let w = rx2 - lx;
            let h = by - ty;
            if (w - h).abs() > 0.01 {
                continue;
            }
            // mark used
            used[r][c] = true;
            used[r][c2] = true;
            used[r2][c] = true;
            used[r2][c2] = true;
            for cc in c..=c2 {
