            if r1 + 1 < g.rows && v_conn(g.krc(r1 + 1, c1), g.krc(r1, c1)) {
                x2 = cx(c1);
                y2 = cy(r1);
            }
            pieces.push(Piece {
                x1,
                y1,
                x2,
                y2,
                style,
                start_marker: None,
                end_marker: None,
            });
        }
        _ => {}
    }
    (pieces, extras)
}

// ---------------------------------------------------------------------------
// circles

fn find_circles(g: &Grid, used: &mut Vec<Vec<bool>>, out: &mut Vec<Out>) {
    for r in 0..g.rows {
        for c in 0..g.cols {
            if used[r][c] {
                continue;
            }
            if g.krc(r, c) != Kind::CornerTop {
                continue;
            }
            // try to find a circle with this as top-left corner
            // find the top-right '.' corner going right
            let mut c2 = c + 1;
            let mut tr = None;
            while c2 < g.cols {
                let k = g.krc(r, c2);
                if k == Kind::CornerTop {
                    tr = Some(c2);
                    break;
                }
                if k != Kind::H && k != Kind::Tilde {
                    break;
                }
                c2 += 1;
            }
            let c2 = match tr {
                Some(v) => v,
                None => continue,
            };
            if c2 <= c + 1 {
                continue;
            }
            // bottom row: r+2
            let r2 = r + 2;
            if r2 >= g.rows {
                continue;
            }
            // check the bottom row: cells c+1..c2-1 must be dashes and the corners must be
            // bottom corners
            let bl_ok = g.krc(r2, c) == Kind::CornerBot || g.krc(r2, c) == Kind::CornerApos;
            let br_ok = g.krc(r2, c2) == Kind::CornerApos;
            if !bl_ok || !br_ok {
                continue;
            }
            for cc in c + 1..c2 {
                let k = g.krc(r2, cc);
                if k != Kind::H && k != Kind::Tilde {
                    bl_ok_or(break);
                }
            }
            // check the middle row: '(' at c, ')' at c2
            let rm = r + 1;
            if g.krc(rm, c) != Kind::ParenL || g.krc(rm, c2) != Kind::ParenR {
                continue;
            }
            // check all cells in between are blank or one dash etc
            let mut ok = true;
            for cc in c + 1..c2 {
                let k = g.krc(rm, cc);
                if k != Kind::Blank {
                    ok = false;
                }
            }
            if !ok {
                continue;
            }
            // geometry
            let lx = cx(c);
            let rx2 = cx(c2);
            let ty = cy(r);
            let by = cy(r2);
            let w = rx2 - lx;
            let h = by - ty;
            if (w - h).abs() > 0.01 {
                continue;
            }
            // mark used
            used[r][c] = true;
            used[r][c2] = true;
            used[r2][c] = true;
            used[r2][c2] = true;
            for cc in c..=c2 {
                used[r][cc] = true;
                used[r2][cc] = true;
            }
            for rr in r..=r2 {
                used[rr][c] = true;
                used[rr][c2] = true;
            }
            out.push(Out::Circle {
                cx: lx + w / 2.0,
                cy: ty + h / 2.0,
                r: w / 2.0,
                style: Style::Solid,
            });
        }
    }
}

fn bl_ok_or(_x: bool) {}
