// ---------------------------------------------------------------------------
// text

fn escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}

fn is_blankk(k: Kind) -> bool {
    k == Kind::Blank
}

// ---------------------------------------------------------------------------
// merge & render

pub fn convert(input: &str, opts: &Options) -> String {
    let g = parse_grid(input);
    let out = process(&g, opts);
    render(&g, opts, &out)
}

pub fn process(g: &Grid, opts: &Options) -> Vec<Out> {
    let _ = opts;
    let mut used = vec![vec![false; g.cols]; g.rows];
    let mut out: Vec<Out> = Vec::new();

    let rects = find_rects(g, &mut used);
    for rect in &rects {
        out.push(Out::Rect {
            x: cx(rect.c0),
            y: cy(rect.r0),
            w: cx(rect.c1) - cx(rect.c0),
            h: cy(rect.r1) - cy(rect.r0),
            style: if rect.broken { Style::Broken } else { Style::Solid },
            rx: rect.rx,
        });
    }
    find_circles(g, &mut used, &mut out);

    // special cells with positions
    let mut specials: Vec<((usize, usize), Vec<Out>)> = Vec::new();
    for r in 0..g.rows {
        for c in 0..g.cols {
            if used[r][c] {
                continue;
            }
            match g.krc(r, c) {
                Kind::Block => {
                    specials.push((
                        (r, c),
                        vec![Out::Rect {
                            x: cx(c) - HW,
                            y: cy(r) - HW,
                            w: CW,
                            h: CW,
                            style: Style::Solid,
                            rx: 0.0,
                        }],
                    ));
                    used[r][c] = true;
                }
                Kind::Double => {
                    specials.push((
                        (r, c),
                        vec![
                            Out::Line {
                                x1: left(c),
                                y1: cy(r) - 2.0,
                                x2: right(c),
                                y2: cy(r) - 2.0,
                                style: Style::Solid,
                                start_marker: None,
                                end_marker: None,
                            },
                            Out::Line {
                                x1: left(c),
                                y1: cy(r) + 2.0,
                                x2: right(c),
                                y2: cy(r) + 2.0,
                                style: Style::Solid,
                                start_marker: None,
                                end_marker: None,
                            },
                        ],
                    ));
                    used[r][c] = true;
                }
                _ => {}
            }
        }
    }

    // runs
    let runs = collect_runs(g, &used);
    let mut run_used = vec![vec![false; g.cols]; g.rows];
    for seg in &runs {
        for &(r, c) in &seg.cells {
            run_used[r][c] = true;
        }
    }

    // text runs
    let mut texts: Vec<((usize, usize), Out)> = Vec::new();
    for r in 0..g.rows {
        let mut c = 0usize;
        while c < g.cols {
            if used[r][c] || is_blankk(g.krc(r, c)) {
                c += 1;
                continue;
            }
            let start = c;
            let mut end = c;
            while end + 1 < g.cols
                && !used[r][end + 1]
                && !is_blankk(g.krc(r, end + 1))
            {
                end += 1;
            }
            let mut content = String::new();
            for cc in start..=end {
                content.push(g.ch(r, cc));
            }
            texts.push((
                (r, start),
                Out::Text {
                    x: left(start) + 2.0,
                    y: cy(r) + 4.0,
                    content: escape(&content),
                },
            ));
            c = end + 1;
        }
    }

    // merge events in row-major order
    let mut events: Vec<((usize, usize), usize)> = Vec::new(); // (pos, kind) kind:0=special 1=text 2=run
    for (i, s) in specials.iter().enumerate() {
        events.push((s.0, 100000 + i));
    }
    for (i, t) in texts.iter().enumerate() {
        events.push((t.0, 200000 + i));
    }
    for (i, s) in runs.iter().enumerate() {
        events.push((s.start(), 300000 + i));
    }
    events.sort();

    for (_pos, code) in events {
        if code < 200000 {
            let i = code - 100000;
            for e in &specials[i].1 {
                out.push(e.clone());
            }
        } else if code < 300000 {
            let i = code - 200000;
            out.push(texts[i].1.clone());
        } else {
            let i = code - 300000;
            let seg = &runs[i];
            let (pieces, extras) = if seg.dir == Dir::H {
                h_run_out(g, seg)
            } else if seg.dir == Dir::V {
                v_run_out(g, seg)
            } else {
                diag_run_out(g, seg)
            };
            let pieces: Vec<Piece> = pieces
                .into_iter()
                .filter(|p| p.length() > 0.01)
                .collect();
            emit_pieces(&mut out, pieces, extras);
        }
    }
    out
}

fn emit_pieces(out: &mut Vec<Out>, pieces: Vec<Piece>, extras: Vec<Out>) {
    // find existing line that any new piece touches
    let mut target: Option<usize> = None;
    for p in &pieces {
        for (oi, o) in out.iter().enumerate() {
            if line_touches(o, p) {
                target = Some(oi);
                break;
            }
        }
        if target.is_some() {
            break;
        }
    }
    if let Some(oi) = target {
        let existing: Vec<Out> = match out[oi].clone() {
            Out::Line {
                ..
            } => vec![out[oi].clone()],
            Out::Group(v) => v,
            other => vec![other],
        };
        let mut v = existing;
        for p in pieces {
            v.push(p.to_out());
        }
        out[oi] = Out::Group(v);
        for e in extras {
            out.push(e);
        }
    } else {
        for p in pieces {
            out.push(p.to_out());
        }
        for e in extras {
            out.push(e);
        }
    }
}

fn line_touches(o: &Out, p: &Piece) -> bool {
    let (x1, y1, x2, y2) = match o {
        Out::Line {
            x1,
            y1,
            x2,
            y2,
            ..
        } => (*x1, *y1, *x2, *y2),
        _ => return false,
    };
    let minx = x1.min(x2) - 0.6;
    let maxx = x1.max(x2) + 0.6;
    let miny = y1.min(y2) - 0.6;
    let maxy = y1.max(y2) + 0.6;
    let on_box = |x: f32, y: f32| x >= minx && x <= maxx && y >= miny && y <= maxy;
    on_box(p.x1, p.y1) || on_box(p.x2, p.y2)
}
