fn corner_ok_for(g: &Grid, r: usize, c: usize, which: u8) -> bool {
    let k = g.k(r as isize, c as isize);
    match which {
        0 | 1 => k == Kind::Plus || k == Kind::CornerTop,
        2 => k == Kind::Plus || k == Kind::CornerBot || k == Kind::CornerApos,
        3 => k == Kind::Plus || k == Kind::CornerApos,
        _ => false,
    }
}

fn count_conns(g: &Grid, r: usize, c: usize) -> usize {
    let mut n = 0;
    for (dr, dc) in [(0isize, -1isize), (0, 1), (-1, 0), (1, 0)] {
        let nr = r as isize + dr;
        let nc = c as isize + dc;
        let a = g.k(nr, nc);
        let b = g.k(r as isize, c as isize);
        let conn = if dr == 0 {
            if dc < 0 {
                h_conn(a, b)
            } else {
                h_conn(b, a)
            }
        } else if dr < 0 {
            v_conn(a, b)
        } else {
            v_conn(b, a)
        };
        if conn {
            n += 1;
        }
    }
    n
}

fn edge_cells_ok(g: &Grid, r: usize, c0: usize, c1: usize) -> bool {
    for c in c0 + 1..c1 {
        let k = g.k(r as isize, c as isize);
        if k != Kind::H && k != Kind::Tilde {
            return false;
        }
    }
    true
}
fn vedge_cells_ok(g: &Grid, c: usize, r0: usize, r1: usize) -> bool {
    for r in r0 + 1..r1 {
        let k = g.k(r as isize, c as isize);
        if k != Kind::V {
            return false;
        }
    }
    true
}

fn h_connected_cells(g: &Grid, r1: usize, c1: usize, r2: usize, c2: usize) -> bool {
    h_conn(g.k(r1 as isize, c1 as isize), g.k(r2 as isize, c2 as isize))
}
fn v_connected_cells(g: &Grid, r1: usize, c1: usize, r2: usize, c2: usize) -> bool {
    v_conn(g.k(r1 as isize, c1 as isize), g.k(r2 as isize, c2 as isize))
}

fn has_conn(g: &Grid, r: usize, c: usize, dr: isize, dc: isize) -> bool {
    let nr = r as isize + dr;
    let nc = c as isize + dc;
    let a = g.k(nr, nc);
    let b = g.k(r as isize, c as isize);
    if dr == 0 {
        if dc < 0 {
            h_conn(a, b)
        } else {
            h_conn(b, a)
        }
    } else if dr < 0 {
        v_conn(a, b)
    } else {
        v_conn(b, a)
    }
}

fn tl_valid(g: &Grid, r: usize, c: usize) -> bool {
    has_conn(g, r, c, 0, 1) && has_conn(g, r, c, 1, 0) && count_conns(g, r, c) == 2
}
fn tr_valid(g: &Grid, r: usize, c: usize) -> bool {
    has_conn(g, r, c, 0, -1) && has_conn(g, r, c, 1, 0) && count_conns(g, r, c) == 2
}
fn bl_valid(g: &Grid, r: usize, c: usize) -> bool {
    has_conn(g, r, c, 0, 1) && has_conn(g, r, c, -1, 0) && count_conns(g, r, c) == 2
}
fn br_valid(g: &Grid, r: usize, c: usize) -> bool {
