            if let Some(m) = marker_of(kb) {
                em = Some(m);
            }
        }
        let mut sm: Option<Marker> = None;
        if a > 0 {
            if let Some(m) = marker_of(g.krc(seg.cells[a - 1].0, c)) {
                sm = Some(m);
            }
        }
        let mut broken = false;
        for i in a..=b {
            if g.krc(seg.cells[i].0, c) == Kind::Tilde {
                broken = true;
            }
        }
        if y2 > y1 + 0.01 {
            pieces.push(Piece {
                x1: x,
                y1,
                x2: x,
                y2,
                style: if broken { Style::Broken } else { Style::Solid },
                start_marker: sm,
                end_marker: em,
            });
        }
    }
    let k0 = g.krc(seg.cells[0].0, c);
    if let Some(m) = marker_of(k0) {
        let r0 = seg.cells[0].0;
        let ccy = cy(r0);
        pieces.insert(
            0,
            Piece {
                x1: x,
                y1: ccy + HW,
                x2: x,
                y2: ccy,
                style: Style::Solid,
                start_marker: None,
                end_marker: Some(m),
            },
        );
    }
    for &i in &bidx {
        let r = seg.cells[i].0;
        let k = g.krc(r, c);
        if let Some(m) = marker_of(k) {
            if i == 0 {
                continue;
            }
            let has_up = i > 0 && v_conn(g.krc(seg.cells[i - 1].0, c), g.krc(r, c));
            let has_down = i + 1 < n && v_conn(g.krc(r, c), g.krc(seg.cells[i + 1].0, c));
            let ccy = cy(r);
            if has_down && !has_up {
                extras.push(Out::Line {
                    x1: x,
                    y1: ccy + HW,
                    x2: x,
                    y2: ccy,
                    style: Style::Solid,
                    start_marker: None,
                    end_marker: Some(m),
                });
            }
            continue;
        }
        if is_paren(k) {
            let sweep = if k == Kind::ParenL { 0 } else { 1 };
            extras.push(Out::Path {
                d: format!(
                    "M {},{} A 12,12 0,0,{} {},{}",
                    fmt(x),
                    fmt(top(r)),
                    sweep,
                    fmt(x),
                    fmt(bot(r))
                ),
                style: Style::Solid,
            });
            continue;
        }
        if is_v_arrow(k) {
            let points_down = k == Kind::ArrowD;
            let has_up = i > 0 && v_conn(g.krc(seg.cells[i - 1].0, c), g.krc(r, c));
            let has_down = i + 1 < n && v_conn(g.krc(r, c), g.krc(seg.cells[i + 1].0, c));
            let is_start = i == 0;
            let is_end = i == n - 1;
            let away = if is_start {
                points_down == has_down
            } else if is_end {
                points_down != has_up
            } else {
                true
            };
            let tip_y = if points_down { bot(r) } else { top(r) };
            if away {
                let base_y = if points_down { bot(r) - 12.0 } else { top(r) + 12.0 };
                extras.push(Out::Poly {
                    points: format!(
                        "{},{}, {},{}, {},{}",
                        fmt(x - HW),
                        fmt(base_y),
                        fmt(x + HW),
                        fmt(base_y),
                        fmt(tip_y),
                        fmt(x)
                    ),
                });
            } else {
                let wing_y = if points_down { top(r) } else { bot(r) };
                extras.push(Out::Path {
                    d: format!(
                        "M {},{} L {},{} L {},{}",
                        fmt(x - HW),
                        fmt(wing_y),
                        fmt(tip_y),
                        fmt(x),
                        fmt(x + HW),
                        fmt(wing_y)
                    ),
                    style: Style::Solid,
                });
            }
            continue;
        }
    }
    (pieces, extras)
}

fn corner_above(g: &Grid, r: usize, c: usize) -> Option<(usize, usize)> {
    if r == 0 {
        return None;
    }
    let rr = r - 1;
    for cc in [c as isize - 1, c as isize, c as isize + 1] {
        if cc < 0 || cc as usize >= g.cols {
            continue;
        }
        let k = g.krc(rr, cc as usize);
        if k == Kind::CornerTop {
            let hdir = corner_hdir(g, rr, cc as usize);
            let diag_col = cc as isize - hdir as isize;
            if diag_col == c as isize {
                return Some((rr, cc as usize));
            }
        }
    }
    None
}
fn corner_below(g: &Grid, r: usize, c: usize) -> Option<(usize, usize)> {
    if r + 1 >= g.rows {
        return None;
    }
    let rr = r + 1;
    for cc in [c as isize - 1, c as isize, c as isize + 1] {
        if cc < 0 || cc as usize >= g.cols {
            continue;
        }
        let k = g.krc(rr, cc as usize);
        if is_corner(k) && k != Kind::CornerTop {
            let hdir = corner_hdir(g, rr, cc as usize);
            let diag_col = cc as isize - hdir as isize;
            if diag_col == c as isize {
                return Some((rr, cc as usize));
            }
        }
    }
    None
}

// ---------------------------------------------------------------------------
// diagonal runs

fn diag_run_out(g: &Grid, seg: &Seg) -> (Vec<Piece>, Vec<Out>) {
    let mut pieces: Vec<Piece> = Vec::new();
    let extras: Vec<Out> = Vec::new();
    let (r0, c0) = seg.cells[0];
    let (r1, c1) = *seg.cells.last().unwrap();
    let mut broken = false;
    for &(rr, cc) in &seg.cells {
        if g.krc(rr, cc) == Kind::Tilde {
            broken = true;
        }
    }
    let style = if broken { Style::Broken } else { Style::Solid };
    match seg.dir {
        Dir::DSlash => {
            let mut x1 = right(c0);
            let mut y1 = top(r0);
            let mut x2 = left(c1);
            let mut y2 = bot(r1);
            if r0 > 0 && c0 + 1 < g.cols && g.krc(r0 - 1, c0 + 1) == Kind::V {
                x1 = cx(c0 + 1);
                y1 = cy(r0 - 1);
            }
            if r1 + 1 < g.rows && v_conn(g.krc(r1 + 1, c1), g.krc(r1, c1)) {
                x2 = cx(c1);
                y2 = cy(r1);
            }
            pieces.push(Piece {
                x1,
                y1,
                x2,
                y2,
                style,
                start_marker: None,
                end_marker: None,
            });
        }
        Dir::DBack => {
            let mut x1 = left(c0);
            let mut y1 = top(r0);
            let mut x2 = right(c1);
            let mut y2 = bot(r1);
            if r0 > 0 && c0 > 0 && g.krc(r0 - 1, c0 - 1) == Kind::V {
                x1 = cx(c0 - 1);
                y1 = cy(r0 - 1);
            }
            if r1 + 1 < g.rows && v_conn(g.krc(r1 + 1, c1), g.krc(r1, c1)) {
                x2 = cx(c1);
                y2 = cy(r1);
            }
            pieces.push(Piece {
                x1,
                y1,
                x2,
                y2,
                style,
                start_marker: None,
                end_marker: None,
            });
        }
        _ => {}
    }
    (pieces, extras)
}

// ---------------------------------------------------------------------------
// circles

fn find_circles(g: &Grid, used: &mut Vec<Vec<bool>>, out: &mut Vec<Out>) {
    for r in 0..g.rows {
        for c in 0..g.cols {
            if used[r][c] {
                continue;
            }
            if g.krc(r, c) != Kind::CornerTop {
                continue;
            }
            let mut c2 = c + 1;
            let mut tr = None;
            while c2 < g.cols {
                let k = g.krc(r, c2);
                if k == Kind::CornerTop {
                    tr = Some(c2);
                    break;
                }
                if k != Kind::H && k != Kind::Tilde {
                    break;
                }
                c2 += 1;
            }
            let c2 = match tr {
                Some(v) => v,
                None => continue,
            };
            if c2 <= c + 1 {
                continue;
            }
            let r2 = r + 2;
            if r2 >= g.rows {
                continue;
            }
            let mut bl_ok =
                g.krc(r2, c) == Kind::CornerBot || g.krc(r2, c) == Kind::CornerApos;
            let br_ok = g.krc(r2, c2) == Kind::CornerApos;
            if !bl_ok || !br_ok {
                continue;
            }
            for cc in c + 1..c2 {
                let k = g.krc(r2, cc);
                if k != Kind::H && k != Kind::Tilde {
                    bl_ok = false;
                    break;
                }
            }
            if !bl_ok {
                continue;
            }
            let rm = r + 1;
            if g.krc(rm, c) != Kind::ParenL || g.krc(rm, c2) != Kind::ParenR {
                continue;
            }
            let mut ok = true;
            for cc in c + 1..c2 {
                let k = g.krc(rm, cc);
                if k != Kind::Blank {
                    ok = false;
                }
            }
            if !ok {
                continue;
            }
            let lx = cx(c);
            let rx2 = cx(c2);
            let ty = cy(r);
            let by = cy(r2);
            let w = rx2 - lx;
            let h = by - ty;
            if (w - h).abs() > 0.01 {
                continue;
            }
            for cc in c..=c2 {
                used[r][cc] = true;
                used[r2][cc] = true;
            }
            for rr in r..=r2 {
                used[rr][c] = true;
                used[rr][c2] = true;
            }
            out.push(Out::Circle {
                cx: lx + w / 2.0,
                cy: ty + h / 2.0,
                r: w / 2.0,
                style: Style::Solid,
            });
        }
    }
}
