                    let hdir = corner_hdir(g, ra, c);
                    if let Some(arc) = corner_arc(g, ra, c, hdir) {
                        y1 = arc.v_end.1;
                    }
                }
                _ => {}
            }
        } else {
            let pk = g.krc(seg.cells[a - 1].0, c);
            y1 = match pk {
                Kind::MOpen | Kind::MBig | Kind::MDot => cy(seg.cells[a - 1].0) + HW,
                Kind::ArrowU | Kind::ArrowD | Kind::ParenL | Kind::ParenR => {
                    bot(seg.cells[a - 1].0)
                }
                Kind::Block => cy(seg.cells[a - 1].0) - HW,
                _ => bot(seg.cells[a - 1].0),
