                Kind::Block => y2 = cy(rb) - HW,
                Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                    let hdir = corner_hdir(g, rb, c);
                    if let Some(arc) = corner_arc(g, rb, c, hdir) {
