        pieces.insert(
            0,
            Piece {
                x1: x,
                y1: ccy + HW,
                x2: x,
                y2: ccy,
                style: Style::Solid,
                start_marker: None,
                end_marker: Some(m),
            },
        );
    }
    for &i in &bidx {
        let r = seg.cells[i].0;
        let k = g.krc(r, c);
