// ---------------------------------------------------------------------------
// rendering

fn style_str(s: Style) -> &'static str {
    match s {
        Style::Solid => "solid",
        Style::Broken => "broken",
    }
}

fn render_elem(e: &Out, indent: &str, scale: f32, out: &mut String) {
    let s = scale;
    match e {
        Out::Line {
            x1,
            y1,
            x2,
            y2,
            style,
            start_marker,
            end_marker,
        } => {
            let mut cls = style_str(*style).to_string();
            if let Some(m) = start_marker {
                cls.push(' ');
                cls.push_str(&m.class(true));
            }
            if let Some(m) = end_marker {
                cls.push(' ');
                cls.push_str(&m.class(false));
            }
            out.push_str(&format!(
                "{}<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\" class=\"{}\"></line>\n",
                indent,
                fmt(*x1 * s),
                fmt(*y1 * s),
                fmt(*x2 * s),
                fmt(*y2 * s),
                cls
            ));
        }
        Out::Path { d, style } => {
            out.push_str(&format!(
                "{}<path d=\"{}\" class=\"{}\"></path>\n",
                indent,
                d,
                style_str(*style)
            ));
        }
        Out::Circle { cx: cxx, cy: cyy, r, style } => {
            out.push_str(&format!(
                "{}<circle cx=\"{}\" cy=\"{}\" r=\"{}\" class=\"{}\"></circle>\n",
                indent,
                fmt(*cxx * s),
                fmt(*cyy * s),
                fmt(*r * s),
                style_str(*style)
            ));
        }
        Out::Rect { x, y, w, h, style, rx } => {
            out.push_str(&format!(
                "{}<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" class=\"{}\" rx=\"{}\"></rect>\n",
                indent,
                fmt(*x * s),
                fmt(*y * s),
                fmt(*w * s),
                fmt(*h * s),
                style_str(*style),
                fmt(*rx * s)
            ));
        }
        Out::Poly { points } => {
            // scale the points
            let pts = scale_points(points, s);
            out.push_str(&format!(
                "{}<polygon points=\"{}\" class=\"filled\"></polygon>\n",
                indent,
                pts
            ));
        }
        Out::Text { x, y, content } => {
            out.push_str(&format!(
                "{}<text x=\"{}\" y=\"{}\" >{}</text>\n",
                indent,
                fmt(*x * s),
                fmt(*y * s),
                content
            ));
        }
        Out::Group(v) => {
            out.push_str(&format!("{}<g>\n", indent));
            let inner = format!("{}  ", indent);
            for e in v {
                render_elem(e, &inner, s, out);
            }
            out.push_str(&format!("{}</g>\n", indent));
        }
    }
}

fn scale_points(points: &str, s: f32) -> String {
    let mut res = String::new();
    for tok in points.split_whitespace() {
        if !res.is_empty() {
            res.push(' ');
        }
        let parts: Vec<&str> = tok.split(',').collect();
        if parts.len() == 2 {
            let x = parts[0].parse::<f32>().unwrap_or(0.0);
            let y = parts[1].parse::<f32>().unwrap_or(0.0);
            res.push_str(&format!("{},{}", fmt(x * s), fmt(y * s)));
        } else {
            res.push_str(tok);
        }
    }
    res
}

pub fn render(g: &Grid, opts: &Options, out: &[Out]) -> String {
    let s = opts.scale;
    let width = ((g.cols as f32 + 1.0) * CELL_W) * s;
