        "  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{\n  stroke: {};\n  stroke-width: {};\n  stroke-opacity: 1;\n  fill-opacity: 1;\n  stroke-linecap: round;\n  stroke-linejoin: miter;\n}}\n\n.svgbob text {{\n  white-space: pre;\n  fill: {};\n  font-family: {};\n  font-size: {}px;\n}}\n\n.svgbob rect.backdrop {{\n  stroke: none;\n  fill: {};\n}}\n\n.svgbob .broken {{\n  stroke-dasharray: 8;\n}}\n\n.svgbob .filled {{\n  fill: {};\n}}\n\n.svgbob .bg_filled {{\n  fill: {};\n  stroke-width: 1;\n}}\n\n.svgbob .nofill {{\n  fill: {};\n}}\n\n",
        opts.stroke_color,
        num_fmt(opts.stroke_width),
