            ));
        }
    }
    buf.push_str("</style>\n");
    // defs
    buf.push_str("  <defs>\n");
    buf.push_str("    <marker id=\"arrow\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <polygon points=\"0,0 0,4 4,2 0,0\"></polygon>\n    </marker>\n");
    buf.push_str("    <marker id=\"diamond\" viewBox=\"-2 -2 8 8\" refX=\"4\" refY=\"2\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <polygon points=\"0,2 2,0 4,2 2,4 0,2\"></polygon>\n    </marker>\n");
    buf.push_str("    <marker id=\"circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"filled\"></circle>\n    </marker>\n");
    buf.push_str("    <marker id=\"open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <circle cx=\"4\" cy=\"4\" r=\"2\" class=\"bg_filled\"></circle>\n    </marker>\n");
    buf.push_str("    <marker id=\"big_open_circle\" viewBox=\"0 0 8 8\" refX=\"4\" refY=\"4\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\">\n      <circle cx=\"4\" cy=\"4\" r=\"3\" class=\"bg_filled\"></circle>\n    </marker>\n");
    buf.push_str("  </defs>\n");
    // backdrop
    buf.push_str(&format!(
        "  <rect class=\"backdrop\" x=\"0\" y=\"0\" width=\"{}\" height=\"{}\"></rect>\n",
        fmt(width),
        fmt(height)
    ));
    for e in out {
        render_elem(e, "  ", s, &mut buf);
    }
    buf.push_str("</svg>\n");
    buf
}

fn num_fmt(v: f64) -> String {
    format!("{}", v)
