use std::env;
use std::fs;
use std::io::Read;
use std::io::Write;
use std::path::Path;
use std::process::exit;

mod lib;
use lib::{convert, Options};

const VERSION: &str = "svgbob 0.7.6";
const BUILD_VERSION: &str = "executable-build 0.0.1";

struct Matches {
    help: bool,
    version: bool,
    inline: bool,
    background: Option<String>,
    fill_color: Option<String>,
    font_family: Option<String>,
    font_size: Option<String>,
    scale: Option<String>,
    stroke_color: Option<String>,
    stroke_width: Option<String>,
    output: Option<String>,
    input: Option<String>,
    subcommand: Option<String>,
    sub_matches: Option<Vec<String>>,
}

fn usage_str(prog: &str) -> String {
    format!(
        "USAGE:\n    {} [FLAGS] [OPTIONS] [input] [SUBCOMMAND]",
        prog
    )
}

fn main_help(prog: &str) -> String {
    format!(
        "{}\nSvgBobRus is an ascii to svg converter\n\n{}\n\nFLAGS:\n    -h, --help       Prints help information\n    -s               parse an inline string\n    -V, --version    Prints version information\n\nOPTIONS:\n        --background <background>        backdrop background will be filled with this color (default: 'white')\n        --fill-color <fill-color>        solid shapes will be filled with this color (default: 'black')\n        --font-family <font-family>      text will be rendered with this font (default: 'arial')\n        --font-size <font-size>          text will be rendered with this font size (default: 14)\n    -o, --output <output>                where to write svg output [default: STDOUT]\n        --scale <scale>                  scale the entire svg (dimensions, font size, stroke width) by this factor\n                                         (default: 1)\n        --stroke-color <stroke-color>    stroke color for all lines (default: 'black')\n        --stroke-width <stroke-width>    stroke width for all lines (default: 2)\n\nARGS:\n    <input>    svgbob text file or inline string to parse [default: STDIN]\n\nSUBCOMMANDS:\n    build    Batch convert files to svg.\n    help     Prints this message or the help of the given subcommand(s)\n",
        VERSION, usage_str(prog)
    )
}

fn build_help(prog: &str) -> String {
    format!(
        "{}-build 0.0.1\nBatch convert files to svg.\n\nUSAGE:\n    {} build [OPTIONS]\n\nFLAGS:\n    -h, --help       Prints help information\n    -V, --version    Prints version information\n\nOPTIONS:\n    -i, --input <input>      set input file pattern like: *.bob or dir/*.bob\n    -o, --outdir <outdir>    set dir of svg files\n",
        prog, prog
    )
}

fn err_exit(msg: &str, usage: &str) -> ! {
    eprint!(
        "error: {}\n\n{}\n\nFor more information try --help\n",
        msg, usage
    );
    exit(1)
}

fn unknown_arg(arg: &str, usage: &str) -> ! {
    err_exit(
        &format!(
            "Found argument '{}' which wasn't expected, or isn't valid in this context",
            arg
        ),
        usage,
    )
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let prog = args
        .first()
        .map(|p| {
            Path::new(p)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| p.clone())
        })
        .unwrap_or_else(|| "svgbob".to_string());
    let m = parse(&args, &prog);
    if m.help {
        print!("{}", main_help(&prog));
        return;
    }
    if m.version {
        println!("{}", VERSION);
        return;
    }
    if let Some(sub) = &m.subcommand {
        if sub == "build" {
            let sm = m.sub_matches.clone().unwrap_or_default();
            if sm.iter().any(|a| a == "-h" || a == "--help") {
                print!("{}", build_help(&prog));
                return;
            }
            if sm.iter().any(|a| a == "-V" || a == "--version") {
                println!("{}", BUILD_VERSION);
                return;
            }
            build_run(&sm, &prog);
            return;
        }
        if sub == "help" {
            let sm = m.sub_matches.clone().unwrap_or_default();
            if let Some(t) = sm.first() {
                if t == "build" {
                    print!("{}", build_help(&prog));
                    return;
                }
                unknown_arg(t, &usage_str(&prog));
            }
            print!("{}", main_help(&prog));
            return;
        }
        unknown_arg(sub, &usage_str(&prog));
    }
    let mut opts = Options::default();
    if let Some(v) = &m.background {
        opts.background = v.clone();
    }
    if let Some(v) = &m.fill_color {
        opts.fill_color = v.clone();
    }
    if let Some(v) = &m.font_family {
        opts.font_family = v.clone();
    }
    if let Some(v) = &m.font_size {
        match v.parse::<i64>() {
            Ok(n) => opts.font_size = n,
            Err(e) => {
                eprintln!("Illegal value for argument font-size: {}", e);
                exit(1);
            }
        }
    }
    if let Some(v) = &m.scale {
        match v.parse::<f32>() {
            Ok(n) => opts.scale = n,
            Err(e) => {
                eprintln!("Illegal value for argument scale: {}", e);
                exit(1);
            }
        }
    }
    if let Some(v) = &m.stroke_color {
        opts.stroke_color = v.clone();
    }
    if let Some(v) = &m.stroke_width {
        match v.parse::<f64>() {
            Ok(n) => opts.stroke_width = n,
            Err(e) => {
                eprintln!("Illegal value for argument stroke-width: {}", e);
                exit(1);
            }
        }
    }
    let content = if m.inline {
        // line 84 target
        m.input.clone().unwrap().to_string()
    } else {
        match &m.input {
            Some(path) => {
                if !Path::new(path).exists() {
                    eprintln!(
                        "Failed to open input file {}: No such file or directory (os error 2)",
                        path
                    );
                    exit(1);
                }
                // line 88 target
                fs::read_to_string(path).unwrap()
            }
            None => {
                let mut buf = String::new();
                let _ = std::io::stdin().read_to_string(&mut buf);
                buf
            }
        }
    };
    let svg = convert(&content, &opts);
    match &m.output {
        Some(path) => {
            match fs::File::create(path) {
                Ok(mut f) => {
                    let _ = f.write_all(svg.as_bytes());
                }
                Err(e) => {
                    eprintln!("Failed to write to output file {}: {}", path, e);
                    exit(2);
                }
            }
        }
        None => {
            print!("{}", svg);
        }
    }
}

fn build_run(sm: &[String], prog: &str) {
    let mut input: Option<String> = None;
    let mut outdir: Option<String> = None;
    let mut used: Vec<&str> = Vec::new();
    let mut i = 0usize;
    while i < sm.len() {
        let a = &sm[i];
        match a.as_str() {
            "-i" | "--input" => {
                i += 1;
                if i >= sm.len() {
                    err_exit(
                        "The argument '--input <input>' requires a value but none was supplied",
                        &format!(
                            "USAGE:\n    {} build {}",
                            prog,
                            build_usage_opts(&used, "input")
                        ),
                    );
                }
                input = Some(sm[i].clone());
                used.push("input");
            }
            "-o" | "--outdir" => {
                i += 1;
                if i >= sm.len() {
                    err_exit(
                        "The argument '--outdir <outdir>' requires a value but none was supplied",
                        &format!(
                            "USAGE:\n    {} build {}",
                            prog,
                            build_usage_opts(&used, "outdir")
                        ),
                    );
                }
                outdir = Some(sm[i].clone());
                used.push("outdir");
            }
            "-V" | "--version" => {
                println!("{}", BUILD_VERSION);
                return;
            }
            _ => {
                let uopts = if used.is_empty() {
                    "[OPTIONS]".to_string()
                } else {
                    build_usage_opts_all(&used)
                };
                unknown_arg(a, &format!("USAGE:\n    {} build {}", prog, uopts));
            }
        }
        i += 1;
    }
    let inp = input.unwrap_or_default();
    let outd = outdir.unwrap_or_default();
    let (dir, _pattern) = match inp.rfind('/') {
        Some(p) => (inp[..p].to_string(), inp[p + 1..].to_string()),
        None => (String::new(), inp.clone()),
    };
    let dpath = Path::new(&dir);
    if !dpath.is_dir() {
        eprintln!("[Error]: No such dir name is {} !", dir);
        exit(1);
    }
    let ext = if _pattern.contains('.') {
        _pattern.split('.').last().unwrap_or("").to_string()
    } else {
        "bob".to_string()
    };
    let entries = match fs::read_dir(dpath) {
        Ok(e) => e,
        Err(_) => {
            eprintln!("[Error]: No such dir name is {} !", dir);
            exit(1);
        }
    };
    for entry in entries.flatten() {
        let p = entry.path();
        if !p.is_file() {
            continue;
        }
        let name = p.file_name().unwrap().to_string_lossy().to_string();
        let fext = p.extension().and_then(|e| e.to_str()).unwrap_or("").to_string();
        if fext != ext {
            continue;
        }
        let stem = name
            .rfind('.')
            .map(|i| name[..i].to_string())
            .unwrap_or_else(|| name.clone());
        let outpath = match &outdir {
            Some(d) => format!("{}/{}.svg", d, stem),
            None => format!("{}/{}.svg", dir, stem),
        };
        println!("{}{} => {}", dir, name, outpath);
        let _ = fs::read_to_string(&p).map(|content| {
            let svg = convert(&content, &Options::default());
            let _ = fs::File::create(&outpath).map(|mut f| f.write_all(svg.as_bytes()));
        });
    }
    exit(1);
}

fn build_usage_opts(used: &[&str], _missing: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    if used.contains(&"input") {
        parts.push("--input <input>".to_string());
    }
    if used.contains(&"outdir") {
        parts.push("--outdir <outdir>".to_string());
    }
    if parts.is_empty() {
        parts.push("--input <input>".to_string());
    }
    parts.join(" ")
}

fn build_usage_opts_all(used: &[&str]) -> String {
    let mut parts: Vec<String> = Vec::new();
    if used.contains(&"input") {
        parts.push("--input <input>".to_string());
    }
    if used.contains(&"outdir") {
        parts.push("--outdir <outdir>".to_string());
    }
    if parts.is_empty() {
        return "[OPTIONS]".to_string();
    }
    parts.join(" ")
}

fn parse(args: &[String], _prog: &str) -> Matches {
    let mut m = Matches {
        help: false,
        version: false,
        inline: false,
        background: None,
        fill_color: None,
        font_family: None,
        font_size: None,
        scale: None,
        stroke_color: None,
        stroke_width: None,
        output: None,
        input: None,
        subcommand: None,
        sub_matches: None,
    };
    let full_usage = usage_str(_prog);
    let mut i = 1usize;
    while i < args.len() {
        let a = &args[i];
        if a == "build" || a == "help" {
            m.subcommand = Some(a.clone());
            m.sub_matches = Some(args[i + 1..].to_vec());
            return m;
        }
        match a.as_str() {
            "-h" | "--help" => m.help = true,
            "-V" | "--version" => m.version = true,
            "-s" => m.inline = true,
            "-o" | "--output" => {
                i += 1;
                if i >= args.len() {
                    err_exit(
                        "The argument '-o/--output <output>' requires a value but none was supplied",
                        &full_usage,
                    );
                }
                m.output = Some(args[i].clone());
            }
            "--background" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--background <background>' requires a value but none was supplied", &full_usage);
                }
                m.background = Some(args[i].clone());
            }
            "--fill-color" => {
