                }
                m.fill_color = Some(args[i].clone());
            }
            "--font-family" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--font-family <font-family>' requires a value but none was supplied", &full_usage);
                }
                m.font_family = Some(args[i].clone());
            }
            "--font-size" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--font-size <font-size>' requires a value but none was supplied", &full_usage);
                }
                m.font_size = Some(args[i].clone());
            }
            "--scale" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--scale <scale>' requires a value but none was supplied", &full_usage);
                }
                m.scale = Some(args[i].clone());
            }
            "--stroke-color" => {
