        println!("{}{} => {}", dir, name, outpath);
        let _ = fs::read_to_string(&p).map(|content| {
            let svg = convert(&content, &Options::default());
            let _ = fs::File::create(&outpath).map(|mut f| f.write_all(svg.as_bytes()));
        });
    }
    exit(1);
}

fn build_usage_opts(used: &[&str], _missing: &str) -> String {
    let mut parts: Vec<String> = Vec::new();
    if used.contains(&"input") {
        parts.push("--input <input>".to_string());
    }
    if used.contains(&"outdir") {
        parts.push("--outdir <outdir>".to_string());
    }
    if parts.is_empty() {
        parts.push("--input <input>".to_string());
    }
    parts.join(" ")
}

fn build_usage_opts_all(used: &[&str]) -> String {
    let mut parts: Vec<String> = Vec::new();
    if used.contains(&"input") {
        parts.push("--input <input>".to_string());
    }
    if used.contains(&"outdir") {
        parts.push("--outdir <outdir>".to_string());
    }
    if parts.is_empty() {
        return "[OPTIONS]".to_string();
    }
    parts.join(" ")
}

fn parse(args: &[String], _prog: &str) -> Matches {
    let mut m = Matches {
        help: false,
        version: false,
        inline: false,
        background: None,
        fill_color: None,
        font_family: None,
        font_size: None,
        scale: None,
        stroke_color: None,
        stroke_width: None,
        output: None,
        input: None,
        subcommand: None,
        sub_matches: None,
    };
    let full_usage = usage_str(_prog);
    let mut i = 1usize;
    while i < args.len() {
        let a = &args[i];
        if a == "build" || a == "help" {
            m.subcommand = Some(a.clone());
            m.sub_matches = Some(args[i + 1..].to_vec());
            return m;
        }
        match a.as_str() {
            "-h" | "--help" => m.help = true,
            "-V" | "--version" => m.version = true,
            "-s" => m.inline = true,
            "-o" | "--output" => {
                i += 1;
                if i >= args.len() {
                    err_exit(
                        "The argument '-o/--output <output>' requires a value but none was supplied",
                        &full_usage,
                    );
                }
                m.output = Some(args[i].clone());
            }
            "--background" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--background <background>' requires a value but none was supplied", &full_usage);
                }
                m.background = Some(args[i].clone());
            }
            "--fill-color" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--fill-color <fill-color>' requires a value but none was supplied", &full_usage);
                }
                m.fill_color = Some(args[i].clone());
            }
            "--font-family" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--font-family <font-family>' requires a value but none was supplied", &full_usage);
                }
                m.font_family = Some(args[i].clone());
            }
            "--font-size" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--font-size <font-size>' requires a value but none was supplied", &full_usage);
                }
                m.font_size = Some(args[i].clone());
            }
            "--scale" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--scale <scale>' requires a value but none was supplied", &full_usage);
                }
                m.scale = Some(args[i].clone());
            }
            "--stroke-color" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--stroke-color <stroke-color>' requires a value but none was supplied", &full_usage);
                }
                m.stroke_color = Some(args[i].clone());
            }
            "--stroke-width" => {
                i += 1;
                if i >= args.len() {
                    err_exit("The argument '--stroke-width <stroke-width>' requires a value but none was supplied", &full_usage);
                }
                m.stroke_width = Some(args[i].clone());
            }
            _ => {
                if a.starts_with('-') && a.len() > 1 {
                    unknown_arg(a, &full_usage);
                }
                if m.input.is_some() {
                    unknown_arg(a, &full_usage);
                }
                m.input = Some(a.clone());
            }
        }
        i += 1;
    }
    m
}
