    let mut pieces: Vec<Piece> = Vec::new();
    let mut extras: Vec<Out> = Vec::new();
    let r = seg.cells[0].0;
    let y = cy(r);
    let n = seg.cells.len();
    let bidx: Vec<usize> = (0..n).filter(|&i| breaks(g.krc(r, seg.cells[i].1))).collect();
    if bidx.len() == n {
        return (pieces, extras);
    }
    let mut chunks: Vec<(usize, usize)> = Vec::new();
    let mut s = 0usize;
    for &i in &bidx {
        if i > s {
            chunks.push((s, i - 1));
        }
        s = i + 1;
    }
    if s < n {
        chunks.push((s, n - 1));
    }
    for &(a, b) in &chunks {
        let ca = seg.cells[a].1;
        let cb = seg.cells[b].1;
        let ka = g.krc(r, ca);
        let kb = g.krc(r, cb);
        let mut broken = false;
        for i in a..=b {
            if g.krc(r, seg.cells[i].1) == Kind::Tilde {
                broken = true;
            }
        }
        let mut x1 = left(ca);
        let mut x2 = right(cb);
