        if a == 0 {
            match ka {
                Kind::MOpen | Kind::MBig | Kind::MDot => x1 = cx(ca),
                Kind::ArrowL | Kind::ArrowR | Kind::ArrowU | Kind::ArrowD => x1 = right(ca),
                Kind::ParenL => x1 = right(ca),
                Kind::ParenR => x1 = left(ca),
                Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                    let hd = corner_hdir(g, r, ca);
                    if let Some(arc) = corner_arc(g, r, ca, hd) {
                        x1 = arc.h_end.0;
                    }
                }
                Kind::Plus | Kind::V | Kind::Slash | Kind::Back => x1 = cx(ca),
                _ => {}
            }
        } else {
            let pi = seg.cells[a - 1].1;
            let pk = g.krc(r, pi);
            x1 = match pk {
                Kind::MOpen | Kind::MBig => {
                    if a - 1 == 0 {
                        cx(pi) + 12.0
                    } else {
                        cx(pi) + HW
                    }
                }
                Kind::MDot => {
                    if a - 1 == 0 {
                        left(seg.cells[1].1)
                    } else {
                        cx(pi) - HW
                    }
                }
                _ => right(pi),
            };
        }
        // end coordinate
        if b == n - 1 {
            match kb {
                Kind::MOpen | Kind::MBig | Kind::MDot => x2 = cx(cb),
                Kind::ArrowL | Kind::ArrowR | Kind::ArrowU | Kind::ArrowD => x2 = left(cb),
                Kind::ParenL => x2 = right(cb),
                Kind::ParenR => x2 = left(cb),
                Kind::CornerTop | Kind::CornerBot | Kind::CornerApos => {
                    let hd = corner_hdir(g, r, cb);
                    if let Some(arc) = corner_arc(g, r, cb, hd) {
                        x2 = arc.h_end.0;
                    }
                }
                Kind::Plus | Kind::V | Kind::Slash | Kind::Back => x2 = cx(cb),
                _ => {}
            }
        } else {
            let ni = seg.cells[b + 1].1;
            let nk = g.krc(r, ni);
            x2 = match nk {
                Kind::MOpen | Kind::MBig | Kind::MDot => cx(ni),
                _ => left(ni),
            };
        }
        // end marker
        let mut em: Option<Marker> = None;
        let mut end_marker_cell: Option<usize> = None;
        if b == n - 1 {
            if let Some(m) = marker_of(kb) {
                em = Some(m);
                end_marker_cell = Some(cb);
            }
        } else if b + 1 < n {
            let ni = seg.cells[b + 1].1;
            let nk = g.krc(r, ni);
            if let Some(m) = marker_of(nk) {
                em = Some(m);
                end_marker_cell = Some(ni);
            }
        }
        let len = x2 - x1;
        if let (Some(m), Some(mc)) = (em, end_marker_cell) {
            if len < 12.0 - 0.01 {
                // short piece ending at a marker
                let r0 = if m == Marker::BigOpenCircle { 4.0 } else { 3.0 };
                extras.push(Out::Circle {
                    cx: cx(mc),
                    cy: y,
                    r: r0,
                    style: Style::Solid,
                });
                let has_after =
                    mc + 1 < g.cols && h_conn(g.krc(r, mc), g.krc(r, mc + 1));
                if has_after {
                    let mcx = cx(mc);
                    extras.push(Out::Line {
                        x1: mcx + 12.0,
                        y1: y,
                        x2: mcx,
                        y2: y,
                        style: Style::Solid,
                        start_marker: None,
                        end_marker: Some(m),
                    });
                }
                continue;
            }
        }
        if len > 0.01 {
            pieces.push(Piece {
                x1,
                y1: y,
                x2,
                y2: y,
                style: if broken { Style::Broken } else { Style::Solid },
                start_marker: None,
                end_marker: em,
            });
        }
    }
    // after-piece when run ends with a break cell
    if let Some(&i0) = bidx.last() {
        if i0 == n - 1 {
            let c = seg.cells[i0].1;
            let k = g.krc(r, c);
            if k == Kind::MDot {
                let x1 = cx(c) - HW;
                let x2 = cx(c);
                if x2 > x1 + 0.01 {
                    pieces.push(Piece {
                        x1,
                        y1: y,
                        x2,
                        y2: y,
                        style: Style::Solid,
                        start_marker: None,
                        end_marker: None,
                    });
                }
            }
        }
    }
    // stub for marker at run start
    let k0 = g.krc(r, seg.cells[0].1);
    if let Some(m) = marker_of(k0) {
        let c0 = seg.cells[0].1;
        let ccx = cx(c0);
        pieces.insert(
            0,
            Piece {
                x1: ccx + 12.0,
                y1: y,
                x2: ccx,
                y2: y,
                style: Style::Solid,
                start_marker: None,
                end_marker: Some(m),
            },
        );
    }
    // break-cell elements in order
    for &i in &bidx {
        let c = seg.cells[i].1;
        let k = g.krc(r, c);
        if marker_of(k).is_some() {
            if i == 0 {
                continue;
            }
            let has_left = h_conn(g.krc(r, seg.cells[i - 1].1), g.krc(r, seg.cells[i].1));
            let has_right = if i + 1 < n {
                h_conn(g.krc(r, seg.cells[i].1), g.krc(r, seg.cells[i + 1].1))
            } else {
                false
            };
            let ccx = cx(c);
            if has_right && !has_left {
                let m = marker_of(k).unwrap();
                extras.push(Out::Line {
                    x1: ccx + 12.0,
                    y1: y,
                    x2: ccx,
                    y2: y,
                    style: Style::Solid,
                    start_marker: None,
                    end_marker: Some(m),
                });
            }
            continue;
        }
        if is_h_arrow(k) {
            let left_c = left(c);
            let right_c = right(c);
            let points_right = k == Kind::ArrowR;
            let has_left = h_conn(g.krc(r, seg.cells[i - 1].1), g.krc(r, seg.cells[i].1));
            let has_right = if i + 1 < n {
                h_conn(g.krc(r, seg.cells[i].1), g.krc(r, seg.cells[i + 1].1))
            } else {
                false
            };
            let is_start = i == 0;
            let is_end = i == n - 1;
            let away = if is_start && is_end {
                !points_right
            } else if is_start {
                points_right != has_right
            } else if is_end {
                points_right == has_left
            } else {
                true
            };
            let tip = if points_right { right_c } else { left_c };
            let base = if points_right { left_c } else { right_c };
            if away {
                extras.push(Out::Poly {
                    points: format!(
                        "{},{} {},{} {},{}",
                        fmt(base),
                        fmt(y - HW),
                        fmt(tip),
                        fmt(y),
                        fmt(base),
                        fmt(y + HW)
                    ),
                });
            } else {
                extras.push(Out::Path {
                    d: format!(
                        "M {},{} L {},{} L {},{}",
                        fmt(base),
                        fmt(y - HW),
                        fmt(tip),
                        fmt(y),
                        fmt(base),
                        fmt(y + HW)
                    ),
                    style: Style::Solid,
                });
            }
            continue;
        }
        if is_corner(k) {
            let hd = if i + 1 < n
                && h_conn(g.krc(r, seg.cells[i].1), g.krc(r, seg.cells[i + 1].1))
            {
                1
            } else if i > 0 && h_conn(g.krc(r, seg.cells[i - 1].1), g.krc(r, seg.cells[i].1)) {
                -1
            } else {
                0
            };
            if hd != 0 {
                if let Some(arc) = corner_arc(g, r, c, hd) {
                    extras.push(corner_out(&arc));
                }
            }
            continue;
        }
    }
    (pieces, extras)
}
